-- 0020: NFL 2025-season carryover: Micah Parsons (GB DE) torn left ACL (2026-11-23). Generated by scripts/weekly/build-migration.mjs.
--   First NFL 2025-season carryover (owner decision, Nov 23, 2026). season = 2025, so it is never counted in 2026 totals;
--   it shows under "Still recovering from previous seasons" on the NFL home page (same mechanism as NBA 2025-26) until a 'returned' update.
--   Tear: Sun 2025-12-14, Week 15, Packers at Broncos (34-26 loss), Empower Field at Mile High. Non-contact, left knee, chasing Bo Nix late in the 3rd quarter.
--   Team at injury time: Packers (acquired from Dallas before the 2025 season); still GB. Surface comes from the stadium record (natural grass; in-game tear).
--   Confirmed: MRI Dec 15 (NFL.com/Rapoport, ESPN), Packers.com Dec 17 (tests confirmed the ACL tear; placed on IR). Surgery Dec 29, 2025 by Dr. Neal ElAttrache in LA
--   (Journal Sentinel, Packers Wire/ESPN); AP and NFL.com report the meniscus was also repaired. Returned to practice Nov 4, 2026 (PUP window; NFL.com).
--   Nov 23, 2026: medically cleared and set to debut vs the Rams on Nov 25 (Ian Rapoport; NFL.com). Stage game_ready, not returned, until he plays.
--   Bio from ESPN athlete 4361423. League-qualified lookups; idempotent throughout.
-- League-qualified lookups; every statement is guarded, so re-running is a no-op.
SET NAMES utf8mb4;

-- Micah Parsons (NFL GB)
INSERT INTO players (league, first_name, last_name, slug, position, team_id)
SELECT 'NFL', 'Micah', 'Parsons', 'micah-parsons', 'DE', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'GB')
WHERE NOT EXISTS (SELECT 1 FROM players WHERE slug = 'micah-parsons');
UPDATE players SET dob = COALESCE(dob, '1999-05-26'), height_in = COALESCE(height_in, 75), weight_lb = COALESCE(weight_lb, 250), headshot_path = COALESCE(headshot_path, '/players/micah-parsons.png'), team_id = COALESCE((SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'GB'), team_id) WHERE slug = 'micah-parsons' AND league = 'NFL';

-- Tear: micah-parsons ACL 2025-12-14
INSERT INTO injuries (player_id, injury_type, injury_date, season, week, stadium_id, home_away, opponent_id, mechanism, body_side, phase, severity_notes, source)
SELECT p.id, 'ACL', '2025-12-14', 2025,
       15, (SELECT id FROM stadiums WHERE league = 'NFL' AND slug = 'empower-field-at-mile-high'), 'away', (SELECT id FROM teams WHERE league = 'NFL' AND abbreviation = 'DEN'), 'non_contact', 'left', 'regular',
       'Hurt late in the third quarter of the Packers'' 34-26 Week 15 loss at Denver while chasing Broncos quarterback Bo Nix: he took an awkward step, grabbed his left knee and went down without contact, and was helped to the locker room. An MRI the next day confirmed a torn ACL, ending his first season in Green Bay; the Packers placed him on injured reserve on Dec. 17. The meniscus in the same knee was also repaired during his Dec. 29 surgery.',
       'https://www.nfl.com/news/mri-confirms-packers-star-micah-parsons-suffered-torn-acl-vs-broncos'
FROM players p WHERE p.slug = 'micah-parsons' AND p.league = 'NFL'
  AND NOT EXISTS (SELECT 1 FROM injuries i WHERE i.player_id = p.id AND i.injury_type = 'ACL' AND i.injury_date = '2025-12-14');

-- Update: micah-parsons diagnosis 2025-12-15
INSERT INTO progress_updates (injury_id, update_date, stage, status_label, notes, source)
SELECT i.id, '2025-12-15', 'diagnosis', 'Torn ACL confirmed; out for season', 'An MRI confirmed a torn ACL (Ian Rapoport, NFL Network). Packers.com reported on Dec. 17 that tests confirmed a season-ending ACL tear, and the team placed him on injured reserve.', 'https://www.packers.com/news/new-formula-same-goals-for-packers-resurgent-defense-dec-17-2025'
FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'micah-parsons' AND p.league = 'NFL' AND i.injury_type = 'ACL' AND i.injury_date = '2025-12-14'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'diagnosis' AND x.update_date = '2025-12-15');

